input.sparql:
SELECT ?z ?zoneLabel WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zoneLabel .
  FILTER(CONTAINS(?zoneLabel, "ZN_6"))
}

SELECT ?p ?pclass ?tsid WHERE {
  ?p brick:hasLocation ?z .
  ?p a brick:Air_Temperature .
  ?z rdfs:label "DataCenter_mid_ZN_6" .
  ?z a brick:HVAC_Zone .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?pclass ?tsid WHERE {
  ?p brick:hasLocation ?z .
  ?z rdfs:label "DataCenter_mid_ZN_6" .
  ?z a brick:HVAC_Zone .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?pclass ?loc WHERE {
  ?p a brick:Air_Temperature .
  ?p brick:hasLocation ?loc .
  FILTER(CONTAINS(str(?loc), "Zone_F2"))
} LIMIT 30
